from taf.gnb.oam.coam.vdu.releases.vduoam24r2 import vDuOAM24R2
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.get_vnfcs_response_v1 import (
    GetVNFCSASMLicensedV1,
)
from taf.gnb.oam.coam.vdu.schemas.bb_config.get_operation_of_reset_gnss_response import (
    SummaryResponse,
)
from taf.gnb.oam.coam.vdu.schemas.fh_licensed.rf_scan_operation_status import (
    RFScanOperationStatus,
)
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type


class vDuOAM24R3(vDuOAM24R2):
    def start_rf_scan_test(self, ru_dn, signal, antenna=None, antenna_carrier=None, antenna_panel=None, timeout=30, raw=False):
        response = self.fh_licensed_v1.start_rf_scan_test(antenna=antenna,
                                                          ru_dn=ru_dn,
                                                          signal=signal,
                                                          antenna_carrier=antenna_carrier,
                                                          antenna_panel=antenna_panel,
                                                          timeout=timeout)
        return response if raw else RFScanOperationStatus.from_object_dict(response)

    def get_rf_scan_test_operation_status(self, operation_id, timeout=30, raw=False):
        response = self.fh_licensed_v1.get_rf_scan_test_operation_status(operation_id=operation_id, timeout=timeout)
        return response if raw else RFScanOperationStatus.from_object_dict(response)

    def delete_rf_scan_test_operation(self, operation_id, timeout=30):
        self.fh_licensed_v1.delete_rf_scan_test_operation(operation_id=operation_id, timeout=timeout)

    def cancel_rf_scan_test_operation(self, timeout=30, raw=False):
        response = self.fh_licensed_v1.cancel_rf_scan_test_operation(timeout=timeout)
        return response if raw else RFScanOperationStatus.from_object_dict(response)

    def get_rf_scan_test_cancellation_status(self, operation_id, timeout=30, raw=False):
        response = self.fh_licensed_v1.get_rf_scan_test_cancellation_status(operation_id=operation_id, timeout=timeout)
        return response if raw else RFScanOperationStatus.from_object_dict(response)

    def delete_rf_scan_test_cancel_operation(self, operation_id, timeout=30):
        self.fh_licensed_v1.delete_rf_scan_test_cancel_operation(operation_id=operation_id, timeout=timeout)

    def get_rf_scan_test_file(self, local_path, local_file_name, timeout=30):
        return self.fh_licensed_v1.get_rf_scan_test_file(local_path=local_path,
                                                         local_file_name=local_file_name,
                                                         timeout=timeout)

    def reset_gnss(self, gnsse_r_dn, timeout=30):
        return self.bb_config_v1.reset_gnss(gnsse_r_dn=gnsse_r_dn, timeout=timeout).id

    def get_gnss_reset_operation_status(self, operation_id, timeout=30):
        response = self.bb_config_v1.get_gnss_reset_operation_status(operation_id=operation_id, timeout=timeout)
        return SummaryResponse.from_object_dict(response)

    def delete_gnss_reset_operation(self, operation_id, timeout=30):
        return self.bb_config_v1.delete_gnss_reset_operation(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def reset_cells(self, dist_name, graceful_cell_shutdown=False, use_m2m=True, timeout=90):
        if use_m2m:
            response = self.cp_config_licensed.reset_cells(
                dist_name=dist_name, graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)
        else:
            response = self.cp_config.reset_cells(
                dist_name=dist_name, graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)
        return response

    @enforce_use_m2m_type
    def get_vnfcs_states(self, use_m2m=True, timeout=30, raw=False):
        if use_m2m:
            vnfcs_info_list = self.asm_licensed_v1.get_vnfcs_states(timeout=timeout)
        else:
            vnfcs_info_list = self.asm_v1.get_vnfcs_states(timeout=timeout)

        return vnfcs_info_list if raw else GetVNFCSASMLicensedV1.from_object_dict(vnfcs_info_list)

    def get_counter_objects(self, counter_id, timeout=30):
        return self.pm_v2.get_counter_objects(counter_id=counter_id, timeout=timeout)
